pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, address recipient, uint256 amount) public {
        vm.assume(caller != address(this));
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        vm.assume(amount > 0);

        vm.deal(address(c), amount);

        uint256 recipientBefore = recipient.balance;

        vm.prank(caller);
        bool ok;
        try c.withdrawAll(recipient) { ok = true; } catch { ok = false; }

        uint256 recipientAfter = recipient.balance;
        bool balanceIncreased = recipientAfter > recipientBefore;

        assertTrue(!balanceIncreased || (caller == address(this)));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address recipient, address caller) public {
        bool revertOwner;
        bool revertNonOwner;
        require(caller != c.owner());
        if (address(this).balance > 0) {
            payable(address(0)).transfer(address(this).balance);
        }
        revertOwner = _callWithdraw(c.owner(), recipient);
        revertNonOwner = _callWithdraw(caller, recipient);
        assert(!revertOwner && revertNonOwner);
    }
    function _callWithdraw(address caller, address recipient) internal returns (bool) {
        bool success;
        bytes memory data = abi.encodeWithSignature("withdrawAll(address)", recipient);
        assembly {
            success := call(gas(), sload(c.slot), 0, add(data, 32), mload(data), 0, 0)
            if iszero(success) { success := 1 } 
            if iszero(iszero(returndatasize())) { revert(0,0) }
        }
        return !success;
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
