        require(true);
        bool reverted;
        bool isOwner = (address(this) == c.owner());
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        assert(reverted != isOwner);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address _recipient) public payable {
        require(_recipient != address(0) && uint160(_recipient) < type(uint160).max);
        address shifted = address(uint160(_recipient) + 1);
        uint256 balBeforeRecipient = _recipient.balance;
        uint256 balBeforeShifted = shifted.balance;
        uint256 balC = address(c).balance;
        c.withdrawAll(_recipient);
        assert(_recipient.balance == balBeforeRecipient + balC && shifted.balance == balBeforeShifted);
    }
}

contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	function test(address _recipient, uint _amount) public payable {
		require(_recipient != address(0) && _amount > 0);
		(bool ok, ) = payable(address(c)).call{value: _amount}("");
		require(ok);
		uint preRecipient = _recipient.balance;
		uint preContract = address(c).balance;
		c.withdrawAll(_recipient);
		uint postRecipient = _recipient.balance;
		assert(postRecipient - preRecipient == preContract);
	}
	receive() external payable {}
}

